  if (!m) return '';
  const ms = { minuto: 6e4, minute: 6e4, hora: 36e5, hour: 36e5, dia: 864e5, day: 864e5, semana: 6048e5, week: 6048e5, mes: 2592e6, month: 2592e6 }[m[2]];
  return new Date(Date.now() - Number(m[1]) * ms).toISOString();
}

// Hash corto y estable para ids (FNV-1a 32 bits)
function hash(s) {
  let h = 0x811c9dc5;
  for (const c of String(s)) { h ^= c.codePointAt(0); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(36);
}

function claveTituloEmpresa(titulo, empresa) {
  const limpia = (s) => normTxt(s)
    .replace(/\((m|f|h|w|d|x)(\/(m|f|h|w|d|x))*\)/g, ' ')
    .replace(/\b(s\.?l\.?u?|s\.?a\.?|gmbh|ltd|inc|llc|bv)\b\.?/g, ' ')
    .replace(/[^a-z0-9]+/g, ' ').trim();
  return `${limpia(titulo)}|${limpia(empresa)}`;
}

// El sandbox de Code de n8n no tiene URL ni URLSearchParams
class QS {
  constructor(o = {}) { this.o = { ...o }; }
  set(k, v) { this.o[k] = v; }
  append(k, v) { this.o[k] = v; }
  toString() { return Object.entries(this.o).map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`).join('&'); }
}

function urlCanonica(u) {
  if (!u) return '';
  const txt = String(u).trim();
  const m = txt.match(/^(https?:)\/\/([^/?#]+)([^?#]*)(?:\?([^#]*))?/i);
  if (!m) return txt;
  const [, protocolo, hostRaw, path, query = ''] = m;
  const host = hostRaw.toLowerCase().replace(/^www\./, '');
  const param = (k) => { const r = query.match(new RegExp(`(?:^|&)${k}=([^&]*)`)); return r ? decodeURIComponent(r[1]) : ''; };
  const li = path.match(/\/jobs\/view\/(?:[^/]*-)?(\d{6,})/);
  if (host.endsWith('linkedin.com') && li) return `https://www.linkedin.com/jobs/view/${li[1]}/`;
  if (host.endsWith('linkedin.com') && param('currentJobId')) return `https://www.linkedin.com/jobs/view/${param('currentJobId')}/`;
  if (host.includes('glassdoor') && param('jobListingId')) return `https://www.glassdoor.es/job-listing/j?jl=${param('jobListingId')}`;
  return `${protocolo}//${host}${path.replace(/\/$/, '')}`;
}

function oferta(o) {
  const descripcion = String(o.descripcion ?? '').slice(0, 4000);
  const titulo = String(o.titulo ?? '').trim();
  const empresa = String(o.empresa ?? '').trim();
  const clave = claveTituloEmpresa(titulo, empresa);
  return {
    _tipo: 'oferta',
    id: hash(clave),
    fuente: o.fuente,
    titulo,
    empresa,
    ubicacion: String(o.ubicacion ?? '').trim(),
    pais: o.pais ?? '',
    modalidad: o.modalidad ?? detectaModalidad(`${titulo} ${o.ubicacion ?? ''} ${descripcion.slice(0, 1500)}`, o.remoto),
    salario_texto: o.salario_texto ?? '',
    salario_min: Number(o.salario_min) || null,
    salario_max: Number(o.salario_max) || null,
    salario_periodo: o.salario_periodo ?? '',
    salario_moneda: o.salario_moneda ?? '',
    idioma: o.idioma ?? detectaIdioma(`${titulo} ${descripcion}`),
    fecha: aIso(o.fecha),
    url: o.url ?? '',
    url_canonica: urlCanonica(o.url),
    clave_dedupe: clave,
    descripcion,
  };
}

const uso = (fuente, peticiones, ofertas, errores, nota = '') =>
  ({ _tipo: 'uso', fuente, peticiones, ofertas, errores, nota });
const fallo = (fuente, mensaje) => ({ _tipo: 'error', fuente, mensaje: String(mensaje).slice(0, 300) });
const mensajeError = (e) => e?.message || e?.description || JSON.stringify(e).slice(0, 300);
// ---- fin helpers ----

// Junta cada respuesta de Claude con su oferta (mismo orden que la entrada del HTTP) y monta la fila de Sheets.
const c = $('Config').first().json;
const prep = $('Preparar scoring').all().map((i) => i.json);
const hoy = new Date().toLocaleString('sv-SE', { timeZone: 'Europe/Madrid' }).slice(0, 16);
const CAT = { '1': '1 · Automatización IA', '2': '2 · Operations/BA', '3': '3 · Customer Success', '4': '4 · AI Ops/Evaluación', '5': '5 · CX Ops/T&S', '6': '6 · Datos/BI', bonus: 'Bonus · PO/IT BP', ninguna: 'Ninguna' };
const filas = [];
let errores = [], tin = 0, tout = 0, tcache = 0;
$input.all().forEach(({ json: r }, i) => {
  const o = prep[i]?.oferta;
  if (!o) return;
  if (r.error) { errores.push(`${o.titulo}: ${mensajeError(r.error)}`); return; }
  tin += (r.usage?.input_tokens ?? 0) + (r.usage?.cache_creation_input_tokens ?? 0);
  tcache += r.usage?.cache_read_input_tokens ?? 0;
  tout += r.usage?.output_tokens ?? 0;
  if (r.stop_reason === 'refusal' || r.stop_reason === 'max_tokens') { errores.push(`${o.titulo}: stop_reason=${r.stop_reason}`); return; }
  let s;
  try { s = JSON.parse((r.content ?? []).find((b) => b.type === 'text')?.text); }
  catch (e) { errores.push(`${o.titulo}: JSON inválido`); return; }
  const descartada = s.salario_por_debajo_minimo === true;
  filas.push({
    id: o.id,
    fecha_detectada: hoy,
    score: s.score,
    categoria: CAT[s.puesto_categoria] ?? s.puesto_categoria,
    titulo: o.titulo,
    empresa: o.empresa,
    ubicacion: o.ubicacion,
    modalidad: o.modalidad,
    salario_publicado: o.salario_texto || (o.salario_max ? `${o.salario_min ?? ''}-${o.salario_max} ${o.salario_moneda} ${o.salario_periodo}` : ''),
    salario_estimado_neto_mes: s.salario_estimado_neto_mes ?? '',
    idioma: o.idioma,
    fecha_publicacion: o.fecha ? o.fecha.slice(0, 10) : '',
    fuente: o.fuente,
    url: o.url,
    motivos_match: (s.motivos_match ?? []).join(' · '),
    gaps: (s.gaps ?? []).join(' · '),
    red_flags: [...(s.red_flags ?? []), ...(s.posible_oferta_fantasma ? ['⚠️ posible oferta fantasma'] : [])].join(' · '),
    resumen: s.resumen,
    estado: descartada ? 'Descartado' : 'Por postular',
    fecha_postulacion: '',
    fecha_respuesta: '',
    notas: descartada ? 'Auto: salario por debajo del mínimo' : '',
    clave_dedupe: o.clave_dedupe,
    descripcion: o.descripcion ?? '',
  });
});
// Coste Haiku 5.5: 0,10 $/MTok entrada, 0,50 $/MTok salida, lectura de caché 0,01 $/MTok
const coste = (tin * 0.10 + tcache * 0.01 + tout * 0.50) / 1e6;
$getWorkflowStaticData('global').ultimoScoring = { llamadas: prep.length, ok: filas.length, errores, tin, tcache, tout, coste };
return filas.map((f) => ({ json: f }));

// Mensajes de Telegram para score >= umbral (texto HTML + URL del botón)
const c = $('Config').first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return $('Parsear score').all().map((i) => i.json).filter((f) => f.estado !== 'Descartado' && !f.red_flags.includes('fantasma') && Number(f.score) >= c.SCORE_ALERTA).map((f) => {
  const lineas = [
    `🔥 <b>${f.score}/100</b> · ${esc(f.categoria)}`,
    `<b>${esc(f.titulo)}</b> — ${esc(f.empresa || '¿empresa?')}`,
    `📍 ${esc(f.ubicacion || '?')} · ${esc(f.modalidad)}`,
    `💶 ${esc(f.salario_publicado || 'no indicado')}${f.salario_estimado_neto_mes ? ` (≈${f.salario_estimado_neto_mes} € netos/mes)` : ''}`,
    f.motivos_match && `✅ ${esc(f.motivos_match)}`,
    f.gaps && `⚠️ ${esc(f.gaps)}`,
    f.red_flags && `🚩 ${esc(f.red_flags)}`,
    `<a href="${esc(f.url)}">Ver oferta</a> · ${esc(f.fuente)}`,
  ].filter(Boolean);
  const cvUrl = `${c.N8N_BASE_URL.replace(/\/$/, '')}/webhook/cv-adaptado?id=${encodeURIComponent(f.id)}`;
  return { json: { texto: lineas.join('\n').slice(0, 4000), cv_url: cvUrl } };
});

// Filas para la hoja Uso_API: una por fuente, una por uso de Claude (extracción y scoring) y otra con el resumen de filtros.
const todo = $('Unir fuentes').all().map((i) => i.json);
const f = $getWorkflowStaticData('global').ultimoFiltrado ?? {};
const ahora = new Date().toLocaleString('sv-SE', { timeZone: 'Europe/Madrid' }).slice(0, 16);
const filas = todo.filter((x) => x._tipo === 'uso').map((u) => ({
  fecha: ahora, ejecucion: $execution.id, fuente: u.fuente, peticiones: u.peticiones,
  ofertas: u.ofertas, errores: u.errores, tokens_in: '', tokens_out: '', coste_usd: '', nota: u.nota,
}));
for (const t of todo.filter((x) => x._tipo === 'tokens')) {
  filas.push({ fecha: ahora, ejecucion: $execution.id, fuente: t.fuente, peticiones: t.llamadas, ofertas: '', errores: '',
    tokens_in: t.input_tokens, tokens_out: t.output_tokens, coste_usd: ((t.input_tokens * 0.10 + t.output_tokens * 0.50) / 1e6).toFixed(4), nota: '' });
}
filas.push({ fecha: ahora, ejecucion: $execution.id, fuente: 'filtros', peticiones: 0, ofertas: f.candidatas ?? 0, errores: '',
  tokens_in: '', tokens_out: '', coste_usd: '',
  nota: `recibidas ${f.recibidas ?? 0} → candidatas ${f.candidatas ?? 0} → a puntuar ${f.puntuadas ?? 0}. Descartes: ${Object.entries(f.descartes ?? {}).map(([k, v]) => `${k}: ${v}`).join(', ')}` });
const sc = $getWorkflowStaticData('global').ultimoScoring;
if (sc) filas.push({ fecha: ahora, ejecucion: $execution.id, fuente: 'claude-scoring', peticiones: sc.llamadas, ofertas: sc.ok,
  errores: sc.errores.length, tokens_in: sc.tin + sc.tcache, tokens_out: sc.tout, coste_usd: sc.coste.toFixed(4), nota: `caché leída: ${sc.tcache} tokens` });
return filas.map((json) => ({ json }));

// Un único mensaje de Telegram con todos los fallos de la ejecución (fuentes + scoring)
const fuentes = $('Unir fuentes').all().map((i) => i.json).filter((x) => x._tipo === 'error');
const scoring = $getWorkflowStaticData('global').ultimoScoring?.errores ?? [];
if (!fuentes.length && !scoring.length) return [];
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const lineas = ['⚠️ <b>Job hunter: errores en la ejecución</b>',
  ...fuentes.map((e) => `• <b>${esc(e.fuente)}</b>: ${esc(e.mensaje)}`),
  ...scoring.slice(0, 10).map((e) => `• <b>scoring</b>: ${esc(e)}`),
  'El resto de fuentes se ha procesado con normalidad.'];
return [{ json: { texto: lineas.join('\n').slice(0, 4000) } }];

// Resumen diario: ofertas detectadas hoy por debajo del umbral + uso de APIs del día
const c = $('Config').first().json;
const hoy = new Date().toLocaleString('sv-SE', { timeZone: 'Europe/Madrid' }).slice(0, 10);
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const filas = $('Leer ofertas (resumen)').all().map((i) => i.json).filter((r) => String(r.fecha_detectada ?? '').startsWith(hoy));
const usoHoy = $input.all().map((i) => i.json).filter((r) => String(r.fecha ?? '').startsWith(hoy));
const altas = filas.filter((r) => Number(r.score) >= c.SCORE_ALERTA && r.estado !== 'Descartado');
const resto = filas.filter((r) => Number(r.score) < c.SCORE_ALERTA && r.estado !== 'Descartado').sort((a, b) => b.score - a.score);
const porFuente = {};
for (const u of usoHoy) { const k = u.fuente; porFuente[k] ??= { pet: 0, err: 0, coste: 0 }; porFuente[k].pet += Number(u.peticiones) || 0; porFuente[k].err += Number(u.errores) || 0; porFuente[k].coste += Number(u.coste_usd) || 0; }
const mes = hoy.slice(0, 7);
const jsearchMes = $input.all().map((i) => i.json).filter((r) => r.fuente === 'jsearch' && String(r.fecha ?? '').startsWith(mes)).reduce((n, r) => n + (Number(r.peticiones) || 0), 0);
const costeHoy = Object.values(porFuente).reduce((n, v) => n + v.coste, 0);

const lineas = [`📋 <b>Resumen ${hoy}</b>`, `Nuevas hoy: ${filas.length} · ≥${c.SCORE_ALERTA}: ${altas.length} (ya avisadas) · resto: ${resto.length}`, ''];
for (const r of resto.slice(0, 15)) lineas.push(`• <b>${r.score}</b> <a href="${esc(r.url)}">${esc(r.titulo)}</a> — ${esc(r.empresa)} (${esc(r.modalidad)})`);
if (resto.length > 15) lineas.push(`…y ${resto.length - 15} más en la hoja.`);
lineas.push('', '<b>Peticiones hoy</b>: ' + Object.entries(porFuente).filter(([k]) => k !== 'filtros').map(([k, v]) => `${k} ${v.pet}${v.err ? ` (⚠️${v.err})` : ''}`).join(' · '));
lineas.push(`JSearch este mes: ${jsearchMes}/${c.JSEARCH_CUOTA_MES} · Claude hoy: ${costeHoy.toFixed(3)} $`);
return [{ json: { texto: lineas.join('\n').slice(0, 4000) } }];

// Busca la oferta pedida desde el botón de Telegram
